function PVPArenaHonorListRankItem:RefreshUI(rankData)
    local rank = checkNumber(rankData.rank)
    local TxtNumberText
    if rank <= 4 then
        TxtNumberText = rank
    else
        TxtNumberText = string.format("%s-%s", checkInt(rank * 0.5 + 1), rank)
    end
    self.TxtNumber.text = TxtNumberText
    self.TxtName.text   = rankData.name
end

